import numpy as np

def run(mass):
 p=np.array([[78.5,78.3],[66.4,94.5]],float);v=np.array([[-6.2,16.6],[0.,0.]])
 inv=np.array([1/mass,1/1.4]);r=np.array([5.2,4.5]);dt=1/100;out=[p.copy()];vout=[v.copy()]
 for i in range(20,55):
  for k in range(100):
