     a=.36 if j==0 else .55
     v[j,0]=np.sign(v[j,0])*max(0,abs(v[j,0])-a*dt)
   p+=v*dt
   dif=p[0]-p[1];dist=np.linalg.norm(dif)
   if dist<r.sum():
    n=dif/dist;rv=np.dot(v[0]-v[1],n)
    p[0]+=n*(r.sum()-dist)*inv[0]/inv.sum();p[1]-=n*(r.sum()-dist)*inv[1]/inv.sum()
    if rv<0:
     impulse=-(1+.8)*rv/inv.sum();v[0]+=impulse*inv[0]*n;v[1]-=impulse*inv[1]*n
   for j in range(2):
    if p[j,1]>99-r[j]:
     p[j,1]=99-r[j]
     if v[j,1]>0:
      v[j,1]*=-(.4 if j==0 else 0)
      if abs(v[j,1])<.65:v[j,1]=0
  out.append(p.copy());vout.append(v.copy())
 return np.array(out),np.array(vout)
for m in [1,5]:
